// Electron preload script of a Kreft app. Generated by `kreft add electron`.
// kreft-template: electron-preload@1
// The page gets window.kreftDesktop: named functions only. Nothing else of Node.js or Electron reaches it.
const { contextBridge, ipcRenderer } = require('electron');

const listen = (channel) => (callback) => {
  const handler = (_event, payload) => callback(payload);
  ipcRenderer.on(channel, handler);
  return () => ipcRenderer.removeListener(channel, handler); // call the result to stop listening
};

// Your own functions: register them in electron/custom.js with ipcMain.handle('app:name', …) and call them from a page with
// kreftDesktop.invoke('app:name', …). Only channels that start with "app:" are reachable, so a page cannot call the built-in ones.
const OWN = /^app:[A-Za-z0-9_.:-]+$/;
const own = (channel) => {
  if (!OWN.test(String(channel))) throw new Error('kreftDesktop: a channel for your own functions must start with "app:", like "app:ping"');
  return String(channel);
};

const desktop = {
  isElectron: true,
  invoke: (channel, ...args) => ipcRenderer.invoke(own(channel), ...args),
  on: (channel, callback) => listen(own(channel))(callback),      // events your custom.js sends with win.webContents.send('app:name', …)
  getInfo: () => ipcRenderer.invoke('kreft:app-info'),
  minimize: () => ipcRenderer.invoke('kreft:minimize'),
  maximize: () => ipcRenderer.invoke('kreft:maximize'),
  close: () => ipcRenderer.invoke('kreft:close'),
  getMenu: () => ipcRenderer.invoke('kreft:menu'),
  setMenu: (mode) => ipcRenderer.invoke('kreft:menu', mode),
  openDevTools: (mode) => ipcRenderer.invoke('kreft:devtools:open', mode),
  closeDevTools: () => ipcRenderer.invoke('kreft:devtools:close'),
  toggleDevTools: () => ipcRenderer.invoke('kreft:devtools:toggle'),
  notify: (title, body) => ipcRenderer.invoke('kreft:notify', title, body),
  showMessageBox: (options) => ipcRenderer.invoke('kreft:dialog:message', options),
  showOpenDialog: (options) => ipcRenderer.invoke('kreft:dialog:open', options),
  showSaveDialog: (options) => ipcRenderer.invoke('kreft:dialog:save', options),
  onMenu: listen('kreft:menu'),       // a menu entry with an id was clicked: callback(id)
  onTray: listen('kreft:tray'),       // a tray entry with action "emit" was clicked: callback(id)
  onUpdate: listen('kreft:update'),   // { event: 'update-available' | 'update-downloaded' | 'error' | …, info }
  checkForUpdates: () => ipcRenderer.invoke('kreft:update:check'),
  installUpdate: () => ipcRenderer.invoke('kreft:update:install'),
};
contextBridge.exposeInMainWorld('kreftDesktop', desktop);
contextBridge.exposeInMainWorld('__KREFT_ELECTRON__', true);
